production_orders.sync:
function (doc, oldDoc, meta) {
  // Offline-first production orders and planning actions. A planner's phone may CREATE one, as itself,
  // as 'pending'. Only the backend (admin / import) may advance its status.
  if (doc._deleted) { requireAdmin(); if (oldDoc) { channel("planner:" + oldDoc.planner_id); } return; }
  if (!doc.planner_id) { throw({forbidden: "planner_id is required"}); }
  if (oldDoc == null || oldDoc._deleted) {
    requireUser(doc.planner_id);
    if (doc.type !== "request") { throw({forbidden: "type must be 'request'"}); }
    if (doc.status !== "pending") { throw({forbidden: "new production orders must be 'pending'"}); }
    if (doc._id.indexOf("order::" + doc.planner_id + "::") !== 0) { throw({forbidden: "id must be order::<planner_id>::<uuid>"}); }
  } else {
    if (oldDoc.planner_id !== doc.planner_id) { throw({forbidden: "planner_id is immutable"}); }
    requireAdmin();
  }
  channel("planner:" + doc.planner_id);
}
